mapper.select:
select id
from store
where tenant_id = #{tenantId}

select count(*)
from store
where name_key = #{nameKey} and tenant_id != #{tenantId}

mapper.update:
update tenant
set name = #{name}, city = #{city}, updated_at = current_timestamp
where id = #{tenantId}

update store
set business_hours = cast(#{businessHours} as jsonb), updated_at = current_timestamp
where tenant_id = #{tenantId}

update store_onboarding_draft
set status = 'converted', updated_at = current_timestamp
where tenant_id = #{tenantId}

update owner_wechat_identity
set trial_notice_acknowledged_at = coalesce(trial_notice_acknowledged_at, current_timestamp)
where id = #{ownerIdentityId} and tenant_id = #{tenantId}

mapper.select:
select count(*)
from staff_account
where login_name = #{loginName}

  and id != #{excludeStaffId}

mapper.insert:
insert into staff_credential_secret(
  tenant_id, staff_account_id, key_id, cipher_version, nonce, ciphertext
) values (
  #{tenantId}, #{staffId}, #{keyId}, #{cipherVersion}, #{nonce}, #{ciphertext}
)

mapper.update:
update staff_profile
set display_name = #{displayName}, updated_at = current_timestamp
where tenant_id = #{tenantId} and staff_account_id = #{staffId}

update staff_account
set password_hash = #{passwordHash}, first_login = true, updated_at = current_timestamp
where tenant_id = #{tenantId} and id = #{staffId}

update staff_account
set status = #{status}, updated_at = current_timestamp
where tenant_id = #{tenantId} and id = #{staffId}

