mapper.select:
select count(*)
from staff_service_binding
where tenant_id = #{tenantId} and service_item_id = #{serviceId} and staff_account_id = #{staffId}

select count(*)
from service_resource_binding
where tenant_id = #{tenantId} and service_item_id = #{serviceId} and resource_id = #{resourceId}

insert into bookable_slot(
  tenant_id, store_id, service_item_id, staff_account_id, resource_id,
  start_at, end_at, capacity, status, cancel_deadline_min
) values (
  #{tenantId}, #{storeId}, #{serviceId}, #{staffId}, #{resourceId},
  #{startAt}, #{endAt}, #{capacity}, #{status}, #{cancelDeadlineMin}
)
returning id

select si.id, si.name as "serviceName", count(distinct b.id)::integer as "bookingCount",
  count(distinct ac.id)::integer as "attendanceCount", count(distinct dr.id)::integer as "deductionCount"
from service_item si
left join bookable_slot bs on bs.service_item_id = si.id and bs.tenant_id = #{tenantId}
left join booking b on b.bookable_slot_id = bs.id and b.tenant_id = #{tenantId}
left join attendance_confirm ac on ac.booking_id = b.id and ac.tenant_id = #{tenantId}
left join deduction_record dr on dr.booking_id = b.id and dr.tenant_id = #{tenantId}
where si.tenant_id = #{tenantId}
group by si.id, si.name
order by "bookingCount" desc, si.id

